import { useCallback } from 'react';

import { queryUserShares } from '@proton/shared/lib/api/drive/share';
import { UserShareResult } from '@proton/shared/lib/interfaces/drive/share';

import { shareMetaShortToShare, useDebouncedRequest } from '../_api';
import { useDebouncedFunction } from '../_utils';
import { ShareWithKey } from './interface';
import useShare from './useShare';
import useSharesState from './useSharesState';
import useVolume from './useVolume';

/**
 * useDefaultShare provides access to main default user's share.
 */
export default function useDefaultShare() {
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();
    const sharesState = useSharesState();
    const { getShare, getShareWithKey } = useShare();
    const { createVolume } = useVolume();

    const loadUserShares = useCallback(async (): Promise<void> => {
        const { Shares } = await debouncedRequest<UserShareResult>(queryUserShares());
        const shares = Shares.map(shareMetaShortToShare);
        sharesState.setShares(shares);
    }, []);

    const getDefaultShare = useCallback(
        async (abortSignal?: AbortSignal): Promise<ShareWithKey> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    let defaultShareId = sharesState.getDefaultShareId();

                    // First try to load fresh list of shares from API to make sure
                    // we don't create second default share.
                    if (!defaultShareId) {
                        await loadUserShares();
                        defaultShareId = sharesState.getDefaultShareId();
                    }

                    if (!defaultShareId) {
                        const { shareId } = await createVolume();
                        defaultShareId = shareId;
                        // Load shares to the cache.
                        await loadUserShares();
                    }

                    return getShareWithKey(abortSignal || new AbortController().signal, defaultShareId);
                },
                ['getDefaultShare'],
                abortSignal
            );
        },
        [sharesState.getDefaultShareId, getShareWithKey]
    );

    const isShareAvailable = useCallback(
        async (abortSignal: AbortSignal, shareId: string): Promise<boolean> => {
            const share = await getShare(abortSignal, shareId);
            return !share.isLocked && !share.isVolumeSoftDeleted;
        },
        [getShare]
    );

    return {
        getDefaultShare,
        isShareAvailable,
    };
}

import { act, renderHook } from '@testing-library/react-hooks';

import useDefaultShare from './useDefaultShare';

const mockRequest = jest.fn();
const mockCreateVolume = jest.fn();
const mockGetDefaultShareId = jest.fn();
const mockGetShareWithKey = jest.fn();
const mockGetShare = jest.fn();

jest.mock('../_api/useDebouncedRequest', () => {
    const useDebouncedRequest = () => {
        return mockRequest;
    };
    return useDebouncedRequest;
});

jest.mock('../_utils/useDebouncedFunction', () => {
    const useDebouncedFunction = () => {
        return (wrapper: any) => wrapper();
    };
    return useDebouncedFunction;
});

jest.mock('./useSharesState', () => {
    const useSharesState = () => {
        return {
            setShares: () => {},
            getDefaultShareId: mockGetDefaultShareId,
        };
    };

    return useSharesState;
});

jest.mock('../_shares/useShare', () => {
    const useLink = () => {
        return {
            getShare: mockGetShare,
            getShareWithKey: mockGetShareWithKey,
        };
    };
    return useLink;
});

jest.mock('./useVolume', () => {
    const useVolume = () => {
        return {
            createVolume: mockCreateVolume,
        };
    };
    return useVolume;
});

describe('useDefaultShare', () => {
    let hook: {
        current: ReturnType<typeof useDefaultShare>;
    };

    const defaultShareId = Symbol('shareId');

    beforeEach(() => {
        jest.resetAllMocks();

        mockCreateVolume.mockImplementation(async () => {
            return { shareId: defaultShareId };
        });

        mockRequest.mockImplementation(async () => {
            return { Shares: [] };
        });

        const { result } = renderHook(() => useDefaultShare());
        hook = result;
    });

    it('creates a volume if existing shares are locked/soft deleted', async () => {
        mockGetDefaultShareId.mockImplementation(() => {
            // no valid shares were found
            return undefined;
        });

        await act(async () => {
            await hook.current.getDefaultShare();
        });

        expect(mockCreateVolume.mock.calls.length).toBe(1);
        expect(mockGetShareWithKey).toHaveBeenCalledWith(expect.anything(), defaultShareId);
    });

    it('creates a volume if no shares exist', async () => {
        mockRequest.mockImplementation(async () => {
            return { Shares: [] };
        });

        await act(async () => {
            await hook.current.getDefaultShare();
        });

        expect(mockCreateVolume.mock.calls.length).toBe(1);
        expect(mockGetShareWithKey).toHaveBeenCalledWith(expect.anything(), defaultShareId);
    });

    it("creates a volume if default share doesn't exist", async () => {
        mockRequest.mockImplementation(async () => {
            return {
                Shares: [
                    {
                        isDefault: false,
                    },
                ],
            };
        });

        await act(async () => {
            await hook.current.getDefaultShare();
        });

        expect(mockCreateVolume.mock.calls.length).toBe(1);
        expect(mockGetShareWithKey).toHaveBeenCalledWith(expect.anything(), defaultShareId);
    });

    it.each([
        [{ isLocked: false, isVolumeSoftDeleted: false }, true],
        [{ isLocked: true, isVolumeSoftDeleted: false }, false],
        [{ isLocked: false, isVolumeSoftDeleted: true }, false],
    ])('checks share availability for metadata %p', async (share, expected) => {
        const abortSignal = new AbortController().signal;
        const shareId = 'share-id';
        mockGetShare.mockResolvedValue(share);

        await expect(hook.current.isShareAvailable(abortSignal, shareId)).resolves.toBe(expected);
        expect(mockGetShare).toHaveBeenCalledWith(abortSignal, shareId);
    });
});

import { useEffect, useMemo, useRef, useState } from 'react';
import { Route, RouteComponentProps } from 'react-router';

import { useAppTitle } from '@proton/components';
import { LinkURLType } from '@proton/shared/lib/drive/constants';

import DriveView, { DriveSectionRouteProps } from '../components/sections/Drive/DriveView';
import useActiveShare, { DriveFolder } from '../hooks/drive/useActiveShare';
import { useFolderContainerTitle } from '../hooks/drive/useFolderContainerTitle';
import useNavigate from '../hooks/drive/useNavigate';
import { useDefaultShare, useDriveEventManager } from '../store';
import PreviewContainer from './PreviewContainer';

export default function FolderContainer({ match }: RouteComponentProps<DriveSectionRouteProps>) {
    const { navigateToRoot } = useNavigate();
    const { activeFolder, setFolder } = useActiveShare();
    const lastFolderPromise = useRef<Promise<DriveFolder | undefined>>();
    const [, setError] = useState();
    const { getDefaultShare, isShareAvailable } = useDefaultShare();
    useFolderContainerTitle({ params: match.params, setAppTitle: useAppTitle });
    const events = useDriveEventManager();

    const hasValidLinkType = (type: string) => {
        return type === LinkURLType.FILE || type === LinkURLType.FOLDER;
    };

    const folderPromise = useMemo(async () => {
        const { shareId, type, linkId } = match.params;

        if (!shareId && !type && !linkId) {
            const defaultShare = await getDefaultShare();
            if (defaultShare) {
                return { shareId: defaultShare.shareId, linkId: defaultShare.rootLinkId };
            }
            setError(() => {
                // Throwing error in async function does not propagate it to
                // the view. Therefore we need to use this setError hack.
                throw new Error('Drive is not initilized, cache has been cleared unexpectedly');
            });
        } else if (!shareId || !hasValidLinkType(type as string) || !linkId) {
            console.warn('Missing parameters, should be none or shareId/type/linkId');
            navigateToRoot();
        } else if (type === LinkURLType.FOLDER) {
            if (await isShareAvailable(new AbortController().signal, shareId)) {
                return { shareId, linkId };
            }
            navigateToRoot();
            return;
        }
        return lastFolderPromise.current;
    }, [match.params.shareId, match.params.type, match.params.linkId]);

    useEffect(() => {
        folderPromise
            .then((folder) => {
                if (folder) {
                    setFolder(folder);
                }
            })
            .catch(console.warn);
    }, [folderPromise]);

    // In case we open preview, folder doesn't need to change.
    lastFolderPromise.current = folderPromise;

    const shouldRenderDriveView = Boolean(activeFolder.shareId && activeFolder.linkId);

    useEffect(() => {
        events.shares.startSubscription(activeFolder.shareId).catch(reportError);

        return () => {
            events.shares.pauseSubscription(activeFolder.shareId);
        };
    }, [activeFolder.shareId]);

    return (
        <>
            {shouldRenderDriveView ? <DriveView /> : null}
            <Route path={`/:shareId?/${LinkURLType.FILE}/:linkId?`} component={PreviewContainer} exact />
        </>
    );
}

